# SPDX-License-Identifier: AGPL-3.0-only
from collections import OrderedDict

def solve(payload):
    cache = OrderedDict()
    answers = []
    for operation in payload['operations']:
        key = operation['key']
        if operation['op'] == 'get':
            if key in cache:
                answers.append(cache[key])
            else:
                answers.append(None)
        elif payload['capacity'] > 0:
            cache[key] = operation['value']
            cache.move_to_end(key)
            while len(cache) > payload['capacity']:
                cache.popitem(last=False)
    return {'gets': answers, 'items': [[key, value] for key, value in cache.items()]}

